#' Plot Stochastic Thinning Cross-Validation Folds
#'
#' Visualizes the independent stochastic thinning folds generated by `cv_gbpp`.
#' Displays the original spatial domain alongside the retained test events for
#' each fold, providing a visual diagnostic of the cross-validation
#' spatial balance.
#'
#' @param x An object of class `gbpp_cv`.
#' @param separate Logical. If `TRUE` (default), plots each fold in a separate
#'   panel. If `FALSE`, plots all folds in a single panel with different colors.
#' @param ... Additional arguments passed to `plot()`.
#'
#' @return Invisibly returns the original object `x`.
#' @export
plot.gbpp_cv <- function(x, separate = TRUE, ...) {
  if (!inherits(x, "gbpp_cv")) {
    stop("`x` must be a gbpp_cv object.", call. = FALSE)
  }

  folds <- length(x$folds)

  if (separate) {
    nr <- floor(sqrt(folds))
    nc <- ceiling(folds / nr)

    old_par <- graphics::par(mfrow = c(nr, nc), mar = c(1, 1, 3, 1))
    on.exit(graphics::par(old_par))
    for (k in seq_len(folds)) {
      f <- x$folds[[k]]
      idx_events <- f$y == 1
      locs <- f$locations[idx_events, , drop = FALSE]

      if (!is.null(f$window)) {
        plot(
          f$window,
          main = paste("Fold", k, "\nEvents:", sum(idx_events)),
          ...
        )
      } else {
        plot(
          locs$x, locs$y,
          main = paste("Fold", k, "\nEvents:", sum(idx_events)),
          type = "n", xlab = "", ylab = "", axes = FALSE, ...
        )
      }

      graphics::points(locs$x, locs$y, pch = 20, col = "black", cex = 0.6)
    }
  } else {
    f1 <- x$folds[[1]]
    if (!is.null(f1$window)) {
      plot(f1$window, main = "Stochastic Thinning Folds", ...)
    }

    cols <- grDevices::rainbow(folds)
    for (k in seq_len(folds)) {
      f <- x$folds[[k]]
      idx_events <- f$y == 1
      locs <- f$locations[idx_events, , drop = FALSE]
      graphics::points(locs$x, locs$y, pch = 20, col = cols[k], cex = 0.6)
    }
    graphics::legend(
      "topright", legend = paste("Fold", seq_len(folds)),
      col = cols, pch = 20, bty = "n"
    )
  }

  invisible(x)
}

#' Print Stochastic Thinning Cross-Validation Summary
#'
#' @param x An object of class `gbpp_cv`.
#' @param ... Additional arguments (currently unused).
#'
#' @return Invisibly returns `x`.
#' @export
print.gbpp_cv <- function(x, ...) {
  cat("Stochastic Thinning Cross-Validation Results\n")
  cat("--------------------------------------------\n")
  cat("Number of folds :", length(x$folds), "\n")
  cat("Deviance        :", sprintf("%.4f +/- %.4f\n", x$metrics$deviance_mean, x$metrics$deviance_sd))
  cat("Log-likelihood  :", sprintf("%.4f +/- %.4f\n", x$metrics$loglik_mean, x$metrics$loglik_sd))
  invisible(x)
}
